     *  one per-period sequence are numbered one after the other. */
    @Modifying
    @Query(value = "UPDATE sheet SET last_claim_number = last_claim_number WHERE id = :sheetId", nativeQuery = true)
    int lockSheet(@Param("sheetId") String sheetId);

